pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 a, uint256 b, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(a != 0);
        vm.assume(b <= type(uint256).max - a); // keep a + b admissible for the mutant

        vm.startPrank(actor);
        c.SetMinSum(a);
        c.SetMinSum(b);
        vm.stopPrank();

        // General rule: SetMinSum assigns (does not accumulate), so after the
        // calls above MinSum equals the LAST value passed, b.
        assertTrue(c.MinSum() == b);
    }
}

