pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 val, address logA, address caller) public {
        vm.assume(logA != address(0));
        vm.assume(caller != address(0));

        // Before initialization, SetLogFile works.
        vm.prank(caller);
        c.SetLogFile(logA);
        assertEq(address(c.Log()), logA);

        // Initialization locks configuration forever.
        vm.prank(caller);
        c.Initialized();

