pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, LogFile} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 1 ether);

        // Bind logging to logA before initialization (allowed in both versions).
        LogFile logA = new LogFile();
        c.SetLogFile(address(logA));
        c.SetMinSum(0);
        c.Initialized();

        // First Put: must append a log entry to logA in both versions.
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: amount}("");
        assertTrue(ok1);
        uint256 len1 = logA.History(0) == logA.History(0) ? logLen(logA) : 0;
        assertTrue(len1 >= 1);

        // After initialization, any attempt to re-point the log must have NO effect:
        // the call either reverts (reference) or leaves logging unchanged (reference
        // never follows it), so a later Put MUST still append to logA.
        LogFile logB = new LogFile();
        vm.prank(actor);
        try c.SetLogFile(address(logB)) { /* mutant path: succeeds */ } catch { /* reference path: reverts */ }

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: amount}("");
        assertTrue(ok2);

        uint256 len2 = logLen(logA);
        // General rule: every successful Put appends exactly one entry to the
        // originally bound LogFile. The mutant redirects logging to logB, so the
        // second Put never lands in logA and this fails for the fuzzer-found input.
        assertTrue(len2 == len1 + 1);
    }

    function logLen(LogFile l) internal view returns (uint256 n) {
        // History is a public array getter; probe until out-of-range revert.
        n = 0;
        while (true) {
            try l.History(n) returns (LogFile.Message memory) { n++; }
            catch { break; }
        }
    }
}

