pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    LogFile log;

    function setUp() public {
        c = new C();
        log = new LogFile();
    }

    function testFuzz_property(address actor, uint96 amount, uint64 lockTime) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.warp(1_000_000);

        // Install the LogFile while not initialized, then initialize.
        bool okLog = true;
        try c.SetLogFile(address(log)) {
            okLog = true;
        } catch {
            okLog = false;
        }
        assertTrue(okLog, "SetLogFile must succeed before initialization");
        c.SetMinSum(0);
        c.Initialized();

        // With the LogFile installed, a Put must not revert (it logs to the LogFile).
        vm.deal(actor, amount);
        vm.prank(actor);
        try c.Put{value: amount}(lockTime) {
            assertTrue(true, "Put should succeed");
        } catch {
            assertTrue(false, "Put reverts although LogFile was installed");
        }
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string calldata _data) external {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

