pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface ILog {}

contract LogStub is ILog {}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 salt, address caller) public {
        // deploy a LogFile-compatible contract carrying the fuzzed salt in its code/nonce
        LogStub stub = new LogStub{salt: bytes32(salt)}();
        address logAddr = address(stub);
        vm.assume(logAddr != address(0));

        // drive c through the public entry SetLogFile before initialization
        vm.prank(caller);
        bool ok = true;
        try c.SetLogFile(logAddr) {} catch { ok = false; }

        // General rule: for ANY caller and ANY address with deployed code, a successful
        // pre-initialization SetLogFile(a) must store a, so address(c.Log()) == a.
        // Mutant: Log is never assigned, so c.Log() stays address(0) != a.
        assertTrue(ok && address(c.Log()) == logAddr);
    }
}

