import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address logAddr) public {
        // Admissible domain: any address can serve as a log target pre-initialization.
        vm.assume(logAddr != address(0));

        // First pre-initialization SetLogFile must succeed.
        bool ok1;
        try c.SetLogFile(logAddr) { ok1 = true; } catch { ok1 = false; }

        // Second pre-initialization SetLogFile must also succeed: the lock is
        // always released after each call, so SetLogFile never reverts before
        // Initialized(). The mutant never releases the lock, so this call
        // reverts and the rule breaks.
        bool ok2;
        try c.SetLogFile(logAddr) { ok2 = true; } catch { ok2 = false; }

        assertTrue(ok1 && ok2);
    }
}

